INSERT INTO `wisata_backup_before_osm_sync` VALUES (1,1,'Taman Tempuran Cikal','Alam',4.4,294,5000,10000,-7.840562331,110.4494549,'https://res.cloudinary.com/dfciqrwpe/image/upload/v1749301634/Taman_Tempuran_Cikal_y9ongb.jpg','taman tempuran cikal terletak di kecamatan piyungan di taman ini para pengunjung bisa mencoba bermain dengan beberapa wahana yang ada sembari menikmati kesejukan alam taman tempuran cikal atau biasa disebut ttc terletak di dusun cikal desa srimulyo kecamatan piyungan kabupaten bantul kata tempuran ini diambil dari pertemuan antara dua sungai yaitu sungai gawe dan sungai opak taman tempuran ini telah menjadi salah satu obyek wisata baru di daerah piyungan dan telah dilengkapi dengan beberapa fasilitas seperti wahana speed boat kapal kano atv mini trail flying fox outbound taman bermain gazebo tempat parkir yang luas dan toilet ditaman ini pengunjung juga bisa menikmati macam macam kuliner yang','taman tempur cikal taman tempur cikal letak camat piyungan taman unjung coba main beberapa wahana sembari nikmat sejuk alam taman tempur cikal biasa sebut ttc letak dusun cikal desa srimulyo camat piyungan kabupaten bantul kata tempur ambil temu sungai sungai gawe sungai opak taman tempur jadi salah satu obyek wisata baru daerah piyungan lengkap beberapa fasilitas wahana speed boat kapal kano atv mini trail flying fox outbound taman main gazebo tempat parkir luas toilet tam unjung nikmat macam macam kuliner'),(2,1,'Selopamioro Adventure Park','Alam',4.5,696,30000,30000,-7.945376682,110.4266714,'https://res.cloudinary.com/dfciqrwpe/image/upload/v1749368364/selopamioro-adventure_qhctxz.jpg','kegiatan outbond di lokasi selopamioro adventure park sangat memanjakan para konsumen untuk menikmati alam fasilitas outbond berupa permainan air dan darat dari level anak anak sampai dengan dewasa bisa menjadi rekomendasi anda dan rekan kerja selanjutnya untuk mencoba outbond di selopamioro adventure park','selopamioro adventure park giat outbond lokasi selopamioro adventure park sangat manja konsumen nikmat alam fasilitas outbond upa main air darat level anak anak dewasa jadi rekomendasi rekan kerja lanjut coba outbond selopamioro adventure park'),(3,1,'Tebing Gunung Gajah','Alam',4.5,457,5000,5000,-7.776247027,110.1061368,'https://res.cloudinary.com/dfciqrwpe/image/upload/v1748937502/Tebing-Gunung-Gajah_wuodco.jpg','letaknya di dataran tinggi dengan view pemandangan perbukitan dan menoreh yang hijau dan terdapat waduk sermo di tengahnya selain spot fotonya kemudian juga terdapat spot foto love lock sky bar dan fancy termasuk wahana outbound selain dari beberapa spot fotografi dengan tema tertentu','tebing gunung gajah letak datar tinggi view pandang bukit toreh hijau dapat waduk sermo tengah spot foto kemudian dapat spot foto love lock sky bar fancy masuk wahana outbound beberapa spot fotografi tema tentu'),(4,9,'Restoe Boemi Kreo','Kuliner',4.5,176,0,0,-7.723671547,110.2315140,'https://res.cloudinary.com/dfciqrwpe/image/upload/v1749304595/Restoe_Boemi_Kreo_t8skng.jpg','Restoe Boemi Kreo di kawasan Minggir, Sleman, adalah pilihan tepat. Tempat ini menyajikan konsep cafe sekaligus restoran yang mengusung tema alami dan tradisional. Berlokasi di Jl. Raya Banjararum, Kliran, Sendangagung, Minggir, Sleman, Yogyakarta, Restoe Boemi Kreo memberikan pengalaman menyenangkan dengan suasana pedesaan yang asri dan berbagai spot foto menarik. Dengan latar belakang alam, udara segar, serta tempat yang estetik, Anda bisa menikmati waktu bersantai atau bercengkerama dengan teman-teman maupun keluarga.\r\nFasilitas yang tersedia cukup lengkap untuk menunjang kenyamanan pengunjung. Anda akan menemukan area parkir yang luas, toilet yang bersih, mushola untuk beribadah, serta akses WiFi yang cukup stabil. Spot foto yang menarik tersebar di berbagai sudut, sehingga Anda bisa mengambil gambar dengan latar pemandangan yang indah. Restoe Boemi Kreo juga memiliki outdoor area dengan suasana terbuka dan natural, ideal untuk menikmati suasana Jogja yang khas dan menenangkan.','restoe boemi kreo restoe boemi kreo buah rumah makan hasil karya nextdestinxction masyarakat kreo'),(5,1,'Bukit Paralayang Watugupit','Alam',4.7,9614,5000,5000,-8.026589501,110.3458478,'https://res.cloudinary.com/dfciqrwpe/image/upload/v1749348839/paralayang-watugupit_xyrypb.jpg','seperti namanya bukit ini digunakan sebagai tempat untuk landasan pacu olahraga paralayang para profesional banyak yang berlatih di sini bahkan orang awam pun dapat mencoba paralayang karena terdapat instruktur yang akan mendampingi','bukit paralayang watugupit nama bukit guna tempat landas pacu olahraga paralayang profesional banyak latih sini bahkan orang awam coba paralayang dapat instruktur damping'),(6,1,'Goa Jomblang','Alam',4.6,1064,500000,500000,-8.027954344,110.6382663,'https://res.cloudinary.com/dfciqrwpe/image/upload/v1749364697/goa-jomblang_ze1bb3.jpg','goa jomblang merupakan gua vertikal yang bertipe collapse doline gua ini terbentuk akibat proses geologi amblasnya tanah beserta vegetasi yang ada di atasnya ke dasar bumi yang terjadi ribuan tahun lalu runtuhan ini membentuk sinkhole atau sumuran yang dalam bahasa jawa dikenal dengan istilah luweng saat ini gua jomblang merupakan tempat konservasi tumbuhan purba dan dikembangkan menjadi tempat wisata minat khusus yang mana dikelola oleh penduduk atau warga setempat untuk menuruni gua vertikal ini pihak pengelola sudah menyediakan perlengkapan lengkap sesuai standar keselamatan caving di gua vertikal sinar matahari yang menerobos masuk dari luweng grubug setinggi meter membentuk satu tiang cahaya menyinari flowstone yang indah serta kedalaman gua yang gelap gulita air yang menetes dari ketinggian turut mempercantik pemandangan tidak salah jika banyak orang terkagum kagum datang ke sini ketika menyaksikan lukisan alam yang dikenal dengan istilah cahaya surga','goa jomblang goa jomblang rupa gua vertikal tipe collapse doline gua bentuk akibat proses geologi amblas tanah serta vegetasi atas dasar bumi jadi ribu tahun lalu runtuh bentuk sinkhole sumur bahasa jawa kenal istilah luweng gua jomblang rupa tempat konservasi tumbuh purba kembang jadi tempat wisata minat khusus mana kelola duduk warga tempat turun gua vertikal pihak kelola sedia lengkap lengkap sesuai standar selamat caving gua vertikal sinar matahari terobos masuk luweng grubug setinggi meter bentuk satu tiang cahaya sari flowstone indah dalam gua gelap gulita air tetes tinggi turut cantik pandang salah banyak orang kagum kagum datang sini saksi lukis alam kenal istilah cahaya surga'),(7,1,'Bukit Pengilon','Alam',4.6,439,5000,5000,-8.185458711,110.6917217,'https://res.cloudinary.com/dfciqrwpe/image/upload/v1748937501/bukit_pengilon_qki7sk.jpg','nama bukit pengilon berasal dari bahasa jawa yang berarti cermin karena di bukit ini terdapat batu yang mirip sekali dengan cermin areanya menyejukkan serta sangat luas bahkan saking luasnya destinasi ini banyak wisatawan yang melakukan tracking hingga camping dan mendirikan tenda di sana tak hanya itu tempat satu ini juga akan memanjakan mata anda anda bisa mengabadikan foto dengan pemandangan indah yang berlatar belakang laut','bukit pengilon nama bukit pengilon asal bahasa jawa arti cermin bukit dapat batu mirip sekali cermin area sejuk sangat luas bahkan saking luas destinasi banyak wisatawan laku tracking hingga camping diri tenda sana tak tempat satu manja mata abadi foto pandang indah latar belakang laut'),(8,2,'Taman Sari','Budaya_Dan_Sejarah',4.6,27899,5000,5000,-7.809833449,110.3595117,'https://res.cloudinary.com/dfciqrwpe/image/upload/v1748938870/taman-sari_yy2dq0.jpg','taman sari yogyakarta merupakan salah satu bangunan milik kesultanan yogyakarta yang difungsikan sebagai destinasi wisata namun selain sebagai destinasi wisata taman sari pada saat tertentu juga masih digunakan sebagai tempat ritual oleh keluarga raja dengan bentuk bangunan arsitektur ala portugis jawa bangunan di taman ini menjadi daya tarik utama meskipun sekarang kondisi bangunan tak la